const OPERATIONS = ['add', 'subtract', 'multiply', 'divide'];

const CALCULATOR_SCHEMA = {
  name: TOOL_NAME,
  description: 'Performs basic arithmetic operations (add, subtract, multiply, divide) on two numbers.',
  inputSchema: {
    type: 'object',
    additionalProperties: false,
