      b: { type: 'number' },
      operation: {
        type: 'string',
        enum: OPERATIONS
      }
    },
    required: ['a', 'b', 'operation']
  }
};

export async function listTools() {
  return [CALCULATOR_SCHEMA];
}

function performOperation(a, b, operation) {
  switch (operation) {
    case 'add':
      return a + b;
    case 'subtract':
      return a - b;
    case 'multiply':
      return a * b;
    case 'divide':
      if (b === 0) {
        throw new Error('Division by zero is not allowed');
      }
      return a / b;
    default:
      throw new Error(`Unsupported operation: ${operation}`);
  }
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object with fields: a, b, operation');
  }

  const allowed = new Set(['a', 'b', 'operation']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }
  for (const key of allowed) {
    if (!(key in args)) {
      throw new Error(`Missing required field: ${key}`);
    }
  }

  const { a, b, operation } = args;

  if (typeof a !== 'number' || typeof b !== 'number') {
    throw new Error('Fields "a" and "b" must be numbers');
  }

  if (typeof operation !== 'string' || !OPERATIONS.includes(operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  const result = performOperation(a, b, operation);

  return {
    content: [{ type: 'text', text: String(result) }]
  };
}

