import { listTools, callTool } from './server.mjs';

// Schema sanity check
const [t] = await listTools();
console.log('Tool name:', t.name);
console.log('additionalProperties:', t.inputSchema.additionalProperties);
console.log('required:', t.inputSchema.required);
console.log('operation enum:', t.inputSchema.properties.operation.enum);

// Basic ops
console.log('add 2+3 =', (await callTool('calculate',{a:2,b:3,operation:'add'})).content[0].text);
console.log('sub 10-4 =', (await callTool('calculate',{a:10,b:4,operation:'subtract'})).content[0].text);
console.log('mul 6*7 =', (await callTool('calculate',{a:6,b:7,operation:'multiply'})).content[0].text);
console.log('div 20/4 =', (await callTool('calculate',{a:20,b:4,operation:'divide'})).content[0].text);
console.log('div 5/2 =', (await callTool('calculate',{a:5,b:2,operation:'divide'})).content[0].text);

// Rejection cases
const cases = [
  ['unknown tool', () => callTool('bogus',{a:1,b:2,operation:'add'})],
  ['div by zero', () => callTool('calculate',{a:1,b:0,operation:'divide'})],
  ['unsupported op', () => callTool('calculate',{a:1,b:2,operation:'mod'})],
  ['missing a', () => callTool('calculate',{b:2,operation:'add'})],
  ['missing b', () => callTool('calculate',{a:1,operation:'add'})],
  ['missing op', () => callTool('calculate',{a:1,b:2})],
  ['extra field', () => callTool('calculate',{a:1,b:2,operation:'add',c:99})],
  ['non-numeric a', () => callTool('calculate',{a:'1',b:2,operation:'add'})],
];
for (const [label, fn] of cases) {
  try { await fn(); console.log(label, '=> NO ERROR (BAD)'); }
  catch(e){ console.log(label, '=> rejected:', e.message); }
}
""}

